/*!
 * SciFY cookie consent + Google Analytics loader (no dependencies).
 *
 * Google Analytics is NOT loaded and NO GA cookie is set until the visitor
 * gives consent for the "Analytics" category.
 *
 * SETTINGS: edit /_consent/config.js (Google Analytics ID, privacy URL, language).
 * Do not edit this file for the settings.
 *
 * Every page has in <head>:
 *   <link rel="stylesheet" href="/_consent/consent.css">
 *   <script src="/_consent/config.js"></script>
 *   <script src="/_consent/consent.js" defer></script>
 *
 * Any element with the attribute [data-cookie-settings] opens the preferences
 * dialog. The script also adds a "Cookie settings" link to the page footer.
 * JS API: window.SciFYConsent.open(), .get(), .reset()
 */
(function () {
  'use strict';

  var script = document.currentScript || document.querySelector('script[src*="consent.js"]');
  var CFG = window.SCIFY_CONSENT_CONFIG || {};
  function attr(name) { return (script && script.getAttribute(name)) || ''; }
  var GA_ID = String(CFG.gaId || attr('data-ga-id')).trim();
  var STORAGE_KEY = 'scify-consent-v1';
  var lang = (CFG.lang || attr('data-lang') || document.documentElement.lang || 'en').toLowerCase().slice(0, 2);
  var PRIVACY_URL = CFG.privacyUrl || attr('data-privacy-url') ||
    (lang === 'el' ? 'https://scify.org/privacy-policy/' : 'https://scify.org/en/privacy-policy/');

  var T = {
    en: {
      bannerTitle: 'Cookies for analytics',
      bannerText: 'This site uses only the storage it needs to work. With your consent we also use Google Analytics to understand how the site is used.',
      manage: 'Manage preferences',
      orSee: 'or see our',
      privacy: 'privacy policy',
      reject: 'Reject',
      acceptAnalytics: 'Accept analytics',
      prefsTitle: 'Cookie preferences',
      prefsIntro: 'Choose which optional categories you allow. Strictly-necessary storage is always on.',
      necTitle: 'Strictly necessary',
      necText: 'Remembers your cookie choice so we do not ask again on every page. You cannot turn this off.',
      gaTitle: 'Analytics — Google Analytics',
      gaText: 'Aggregate usage metrics — page views, traffic sources, broad engagement patterns. When this is off, the Google Analytics script is not loaded at all.',
      showCookies: 'Show cookies',
      colName: 'Name', colPurpose: 'Purpose', colProvider: 'Provider', colRetention: 'Retention',
      seeOur: 'See our', fullDetails: 'for full details and your rights.',
      rejectAll: 'Reject all', save: 'Save preferences', acceptAll: 'Accept all',
      close: 'Close', settings: 'Cookie settings',
      cNecPurpose: 'Remembers your cookie-banner choice.', cNecProvider: 'This site (localStorage)', cNecRet: 'Until you clear it',
      cGaPurpose: 'Distinguishes unique users.', cGa2Purpose: 'Persists session state for GA4.', years2: '2 years'
    },
    el: {
      bannerTitle: 'Cookies για στατιστικά',
      bannerText: 'Ο ιστότοπος χρησιμοποιεί μόνο την αποθήκευση που χρειάζεται για να λειτουργεί. Με τη συγκατάθεσή σας χρησιμοποιούμε επίσης το Google Analytics για να κατανοούμε πώς χρησιμοποιείται ο ιστότοπος.',
      manage: 'Διαχείριση προτιμήσεων',
      orSee: 'ή δείτε την',
      privacy: 'πολιτική απορρήτου',
      reject: 'Απόρριψη',
      acceptAnalytics: 'Αποδοχή στατιστικών',
      prefsTitle: 'Προτιμήσεις cookies',
      prefsIntro: 'Επιλέξτε ποιες προαιρετικές κατηγορίες επιτρέπετε. Η απολύτως απαραίτητη αποθήκευση είναι πάντα ενεργή.',
      necTitle: 'Απολύτως απαραίτητα',
      necText: 'Θυμάται την επιλογή σας για τα cookies, ώστε να μη σας ρωτάμε σε κάθε σελίδα. Δεν απενεργοποιείται.',
      gaTitle: 'Στατιστικά — Google Analytics',
      gaText: 'Συγκεντρωτικά στοιχεία χρήσης — προβολές σελίδων, πηγές επισκεψιμότητας, γενικά μοτίβα. Όταν είναι ανενεργό, το Google Analytics δεν φορτώνεται καθόλου.',
      showCookies: 'Εμφάνιση cookies',
      colName: 'Όνομα', colPurpose: 'Σκοπός', colProvider: 'Πάροχος', colRetention: 'Διάρκεια',
      seeOur: 'Δείτε την', fullDetails: 'για όλες τις λεπτομέρειες και τα δικαιώματά σας.',
      rejectAll: 'Απόρριψη όλων', save: 'Αποθήκευση προτιμήσεων', acceptAll: 'Αποδοχή όλων',
      close: 'Κλείσιμο', settings: 'Ρυθμίσεις cookies',
      cNecPurpose: 'Θυμάται την επιλογή σας για τα cookies.', cNecProvider: 'Αυτός ο ιστότοπος (localStorage)', cNecRet: 'Μέχρι να τη διαγράψετε',
      cGaPurpose: 'Διακρίνει μοναδικούς χρήστες.', cGa2Purpose: 'Διατηρεί την κατάσταση συνεδρίας του GA4.', years2: '2 χρόνια'
    }
  };
  var t = T[lang] || T.en;

  var NECESSARY = [{ name: STORAGE_KEY, purpose: t.cNecPurpose, provider: t.cNecProvider, retention: t.cNecRet }];
  var ANALYTICS = [
    { name: '_ga', purpose: t.cGaPurpose, provider: 'Google', retention: t.years2 },
    { name: '_ga_<id>', purpose: t.cGa2Purpose, provider: 'Google', retention: t.years2 }
  ];

  /* ---------- storage ---------- */
  function read() {
    try {
      var v = JSON.parse(window.localStorage.getItem(STORAGE_KEY));
      return v && typeof v === 'object' ? { analytics: !!v.analytics } : null;
    } catch (e) { return null; }
  }
  function write(c) {
    try { window.localStorage.setItem(STORAGE_KEY, JSON.stringify({ analytics: !!c.analytics, ts: new Date().toISOString() })); } catch (e) {}
  }

  /* ---------- Google Analytics ---------- */
  var gaLoaded = false;
  function loadGA() {
    if (gaLoaded || !GA_ID) return;
    gaLoaded = true;
    window.dataLayer = window.dataLayer || [];
    window.gtag = function () { window.dataLayer.push(arguments); };
    window.gtag('js', new Date());
    window.gtag('config', GA_ID, { anonymize_ip: true });
    var s = document.createElement('script');
    s.async = true;
    s.src = 'https://www.googletagmanager.com/gtag/js?id=' + encodeURIComponent(GA_ID);
    document.head.appendChild(s);
  }
  function deleteGACookies() {
    var host = location.hostname, parts = host.split('.'), domains = ['', host];
    for (var i = 1; i < parts.length - 1; i++) domains.push('.' + parts.slice(i).join('.'));
    document.cookie.split(';').forEach(function (c) {
      var name = c.split('=')[0].trim();
      if (/^_ga($|_)|^_gid$|^_gat/.test(name)) {
        domains.forEach(function (d) {
          document.cookie = name + '=; Max-Age=0; path=/' + (d ? '; domain=' + d : '');
        });
      }
    });
  }

  /* ---------- apply ---------- */
  var current = read();
  function apply(c, fromUser) {
    var wasOn = current && current.analytics;
    current = c;
    write(c);
    if (c.analytics) loadGA();
    else if (fromUser && (wasOn || gaLoaded)) {
      // The GA script cannot be unloaded: delete its cookies and reload the page.
      deleteGACookies();
      location.reload();
    } else deleteGACookies();
    removeBanner();
  }
  if (current && current.analytics) loadGA();

  /* ---------- DOM helpers ---------- */
  function el(tag, attrs, children) {
    var n = document.createElement(tag);
    if (attrs) Object.keys(attrs).forEach(function (k) {
      if (k === 'text') n.textContent = attrs[k];
      else if (k.slice(0, 2) === 'on') n.addEventListener(k.slice(2), attrs[k]);
      else n.setAttribute(k, attrs[k]);
    });
    (children || []).forEach(function (c) { if (c) n.appendChild(typeof c === 'string' ? document.createTextNode(c) : c); });
    return n;
  }

  /* ---------- banner ---------- */
  var banner = null;
  function removeBanner() { if (banner) { banner.remove(); banner = null; } }
  function showBanner() {
    if (banner) return;
    banner = el('div', { class: 'scc-banner', role: 'dialog', 'aria-labelledby': 'scc-banner-title', 'aria-live': 'polite' }, [
      el('div', { class: 'scc-banner-inner' }, [
        el('div', { class: 'scc-banner-text' }, [
          el('div', { id: 'scc-banner-title', class: 'scc-banner-title', text: t.bannerTitle }),
          el('div', { class: 'scc-dim' }, [
            t.bannerText + ' ',
            el('button', { type: 'button', class: 'scc-link', text: t.manage, onclick: openPrefs }),
            ' ' + t.orSee + ' ',
            el('a', { href: PRIVACY_URL, target: '_blank', rel: 'noopener', class: 'scc-link-dim', text: t.privacy }),
            '.'
          ])
        ]),
        el('div', { class: 'scc-actions' }, [
          el('button', { type: 'button', class: 'scc-btn', text: t.reject, onclick: function () { apply({ analytics: false }, true); } }),
          el('button', { type: 'button', class: 'scc-btn scc-btn-primary', text: t.acceptAnalytics, onclick: function () { apply({ analytics: true }, true); } })
        ])
      ])
    ]);
    document.body.appendChild(banner);
  }

  /* ---------- preferences dialog ---------- */
  var dialog = null, gaSwitch = null;
  function setSwitch(sw, on) { sw.setAttribute('aria-checked', on ? 'true' : 'false'); }
  function category(title, text, cookies, sw) {
    var tableWrap = el('div', { class: 'scc-table-wrap', hidden: '' }, [
      el('table', { class: 'scc-table' }, [
        el('thead', null, [el('tr', null, [
          el('th', { text: t.colName }), el('th', { text: t.colPurpose }), el('th', { text: t.colProvider }), el('th', { text: t.colRetention })
        ])]),
        el('tbody', null, cookies.map(function (c) {
          return el('tr', null, [el('td', null, [el('code', { text: c.name })]), el('td', { text: c.purpose }), el('td', { text: c.provider }), el('td', { text: c.retention })]);
        }))
      ])
    ]);
    var toggle = el('button', { type: 'button', class: 'scc-show', 'aria-expanded': 'false' }, ['▸ ' + t.showCookies + ' (' + cookies.length + ')']);
    toggle.addEventListener('click', function () {
      var open = toggle.getAttribute('aria-expanded') !== 'true';
      toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
      toggle.textContent = (open ? '▾ ' : '▸ ') + t.showCookies + ' (' + cookies.length + ')';
      if (open) tableWrap.removeAttribute('hidden'); else tableWrap.setAttribute('hidden', '');
    });
    return el('div', { class: 'scc-cat' }, [
      el('div', { class: 'scc-cat-head' }, [
        el('div', { class: 'scc-cat-text' }, [el('div', { class: 'scc-cat-title', text: title }), el('p', { class: 'scc-dim scc-small', text: text })]),
        sw
      ]),
      toggle, tableWrap
    ]);
  }
  function buildDialog() {
    var necSwitch = el('button', { type: 'button', role: 'switch', class: 'scc-switch', 'aria-checked': 'true', 'aria-label': t.necTitle, disabled: '' }, [el('span')]);
    gaSwitch = el('button', { type: 'button', role: 'switch', class: 'scc-switch', 'aria-checked': 'false', 'aria-label': t.gaTitle }, [el('span')]);
    gaSwitch.addEventListener('click', function () { setSwitch(gaSwitch, gaSwitch.getAttribute('aria-checked') !== 'true'); });
    var closeBtn = el('button', { type: 'button', class: 'scc-close', 'aria-label': t.close, text: '×', onclick: closePrefs });

    dialog = el('dialog', { class: 'scc-dialog', 'aria-labelledby': 'scc-prefs-title' }, [
      el('div', { class: 'scc-dialog-head' }, [el('h2', { id: 'scc-prefs-title', text: t.prefsTitle }), closeBtn]),
      el('p', { class: 'scc-dim scc-intro', text: t.prefsIntro }),
      category(t.necTitle, t.necText, NECESSARY, necSwitch),
      category(t.gaTitle, t.gaText, ANALYTICS, gaSwitch),
      el('div', { class: 'scc-dim scc-small scc-privacy' }, [t.seeOur + ' ', el('a', { href: PRIVACY_URL, target: '_blank', rel: 'noopener', text: t.privacy }), ' ' + t.fullDetails]),
      el('div', { class: 'scc-dialog-actions' }, [
        el('button', { type: 'button', class: 'scc-btn', text: t.rejectAll, onclick: function () { closePrefs(); apply({ analytics: false }, true); } }),
        el('button', { type: 'button', class: 'scc-btn', text: t.save, onclick: function () { closePrefs(); apply({ analytics: gaSwitch.getAttribute('aria-checked') === 'true' }, true); } }),
        el('button', { type: 'button', class: 'scc-btn scc-btn-primary', text: t.acceptAll, onclick: function () { closePrefs(); apply({ analytics: true }, true); } })
      ])
    ]);
    // Before the first choice the dialog cannot be dismissed without a decision.
    dialog.addEventListener('cancel', function (e) { if (!current) e.preventDefault(); });
    dialog.addEventListener('click', function (e) { if (e.target === dialog && current) closePrefs(); });
    document.body.appendChild(dialog);
  }
  function openPrefs() {
    if (!dialog) buildDialog();
    setSwitch(gaSwitch, !!(current && current.analytics));
    dialog.querySelector('.scc-close').hidden = !current;
    if (typeof dialog.showModal === 'function') dialog.showModal(); else dialog.setAttribute('open', '');
  }
  function closePrefs() {
    if (!dialog) return;
    if (typeof dialog.close === 'function') dialog.close(); else dialog.removeAttribute('open');
  }

  /* ---------- "Cookie settings" entry point ---------- */
  function addSettingsLink() {
    document.addEventListener('click', function (e) {
      var trg = e.target.closest && e.target.closest('[data-cookie-settings]');
      if (trg) { e.preventDefault(); openPrefs(); }
    });
    if (document.querySelector('[data-cookie-settings]')) return;
    var btn = el('button', { type: 'button', class: 'scc-settings-link', 'data-cookie-settings': '', text: t.settings });
    var footers = document.querySelectorAll('footer, #footer, .footer, .site-footer, .footer_bottom, .footer-bottom');
    var footer = footers[footers.length - 1];
    if (footer) {
      footer.appendChild(el('div', { class: 'scc-settings-wrap' }, [btn]));
    } else {
      btn.classList.add('scc-settings-float');
      document.body.appendChild(btn);
    }
  }

  function init() {
    addSettingsLink();
    if (!current) showBanner();
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();

  window.SciFYConsent = {
    open: openPrefs,
    get: function () { return current; },
    reset: function () { try { localStorage.removeItem(STORAGE_KEY); } catch (e) {} deleteGACookies(); location.reload(); }
  };
})();
